"""Migration of Meridian CRM 4.2 order validation rules."""

from decimal import Decimal
from typing import Any


def _value(record: dict | None, column: str) -> Any:
    """Return a field value, treating a missing field as the empty string."""
    if record is None:
        return ""
    return record.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: the empty string compares as zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Perform a legacy first-live-row LOOKUP."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable order rules in legacy rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            passes = not (
                discount > Decimal("20")
                and _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    owner_uid,
                    "ROLE_ID",
                )
                != "MGR"
                and _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    owner_uid,
                    "ROLE_ID",
                )
                != "ADMIN"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            passes = not (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            if (
                _lookup(
                    tables,
                    "PROD_MASTER",
                    "PROD_ID",
                    product_id,
                    "ACTIVE_FLG",
                )
                != "Y"
            ):
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
